WITH return_summary AS ( SELECT cr.cr_returning_customer_sk, cr.cr_returning_addr_sk, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_net_loss) AS total_net_loss, COUNT(*) AS return_cnt, AVG(cr.cr_return_amount) AS avg_return_amount FROM catalog_returns cr GROUP BY cr.cr_returning_customer_sk, cr.cr_returning_addr_sk ) SELECT r.total_return_amount, r.total_net_loss, r.return_cnt, r.avg_return_amount, c.c_first_name, c.c_last_name, ca.ca_city, ca.ca_country, DENSE_RANK() OVER (ORDER BY r.avg_return_amount DESC) AS avg_return_rank FROM return_summary r JOIN customer c ON r.cr_returning_customer_sk = c.c_customer_sk JOIN customer_address ca ON r.cr_returning_addr_sk = ca.ca_address_sk WHERE ca.ca_country = 'United States' ORDER BY avg_return_rank LIMIT 150
